import { afterEach, expect, it, vi } from "vitest";
import axios from "axios";
vi.mock("@/i18n", () => ({ default: { t: (key: string) => key } }));
vi.mock("@/services/image-storage", () => ({ imageToDataUrl: vi.fn() }));
import { requestGeneration, requestEdit } from "./image";
import { imageToDataUrl } from "@/services/image-storage";
import { defaultConfig } from "@/stores/use-config-store";
const config = { ...defaultConfig, channels: [{ ...defaultConfig.channels[0], apiKey: "user-channel-key" }] };
// Complete 1x1 RGB images generated by Pillow; not signature-only buffers.
const png = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGOQs4kCAAEwALVkUZVDAAAAAElFTkSuQmCC";
const jpeg = "";
const reference = { id: "r", name: "reference.png", type: "image/png", dataUrl: `data:image/png;base64,${png}` };

afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
});
it.each(["generation", "edit"])("uses personal Authorization for %s without access-code headers", async (mode) => {
    vi.stubGlobal("window", { __RUNTIME_CONFIG__: { managedModelGatewayEnabled: true } });
    vi.mocked(imageToDataUrl).mockResolvedValue(reference.dataUrl);
    const post = vi.spyOn(axios, "post").mockResolvedValue({ status: 200, data: { data: [{ b64_json: jpeg }] } });
    const result = await (mode === "generation" ? requestGeneration(config, "test") : requestEdit(config, "test", [reference]));
    expect(post.mock.calls[0][0]).toMatch(/^https:\/\/api.openai.com/);
    expect(post.mock.calls[0][2]?.headers).toMatchObject({ Authorization: "Bearer user-channel-key" });
    expect(post.mock.calls[0][2]?.headers).not.toHaveProperty("X-Managed-Principal");
    expect(result[0].dataUrl).toBe(`data:image/jpeg;base64,${jpeg}`);
});
it("does not substitute an old managed model with a server model", async () => {
    await expect(requestGeneration({ ...config, imageModel: "managed::old", model: "managed::old" }, "test")).rejects.toThrow();
});

// The HTTP Content-Type describes the JSON envelope, not its embedded image.
it.each([
    ["PNG", png, "image/png", "image/jpeg"],
    ["JPEG", jpeg, "image/jpeg", "image/png"],
] as const)("labels real %s bytes correctly despite conflicting declared MIME", async (_format, bytes, expected, declared) => {
    vi.spyOn(axios, "post").mockResolvedValue({ status: 200, headers: { "content-type": "application/json; charset=utf-8" }, data: { data: [{ b64_json: bytes, mime_type: declared }] } });
    const [result] = await requestGeneration(config, "test");
    const response = await fetch(result.dataUrl);
    expect(response.headers.get("content-type")).toBe(expected);
    expect(new Uint8Array(await response.arrayBuffer())).toEqual(Uint8Array.from(atob(bytes), value => value.charCodeAt(0)));
});
it("keeps URL responses without assuming the remote image Content-Type", async () => {
    const url = "https://images.example.test/result.jpg";
    vi.spyOn(axios, "post").mockResolvedValue({ data: { data: [{ url }] } });
    expect((await requestGeneration(config, "test"))[0].dataUrl).toBe(url);
});
